import{_ as t,a,o as n,a6 as d}from"./chunks/framework.CJDy2q7X.js";const m=JSON.parse('{"title":"Theme Impact","description":"","frontmatter":{"outline":false,"apiType":"rest","examples":[{"id":"rest","title":"Theme Impact","query":"curl -X GET \\"https://your-domain.com/api/admin/appearance/themes/velocity/impact?channel_ids[]=1&channel_ids[]=2\\" \\\\\\n  -H \\"Authorization: Bearer <token>\\"\\n","response":"{\\n  \\"code\\": \\"velocity\\",\\n  \\"impact\\": [\\n    { \\"channelId\\": 1, \\"channel\\": \\"Default\\", \\"currentTheme\\": \\"Default\\", \\"customizations\\": 6 }\\n  ]\\n}\\n"},{"id":"rest-none","title":"Nothing Left Behind","query":"curl -X GET \\"https://your-domain.com/api/admin/appearance/themes/default/impact?channel_ids[]=1\\" \\\\\\n  -H \\"Authorization: Bearer <token>\\"\\n","response":"{ \\"code\\": \\"default\\", \\"impact\\": [] }\\n"}]},"headers":[],"relativePath":"api/rest-api/admin/appearance/themes/impact.md","filePath":"api/rest-api/admin/appearance/themes/impact.md","lastUpdated":1789385991000}'),r={name:"api/rest-api/admin/appearance/themes/impact.md"};function i(o,e,h,s,c,l){return n(),a("div",null,e[0]||(e[0]=[d('<h1 id="theme-impact" tabindex="-1">Theme Impact <a class="header-anchor" href="#theme-impact" aria-label="Permalink to &quot;Theme Impact&quot;">​</a></h1><p>What activating a theme on the given channels would leave behind, so the change can be spelled out before anything is written. Reports only; nothing is modified.</p><p>A channel is listed when it currently runs a <strong>different</strong> theme and already holds sections built for it. Those sections are not deleted by activation — they stop being drawn, and return if the channel is pointed back at that theme.</p><h2 id="endpoint" tabindex="-1">Endpoint <a class="header-anchor" href="#endpoint" aria-label="Permalink to &quot;Endpoint&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Method</th><th>Path</th><th>Purpose</th></tr></thead><tbody><tr><td><code>GET</code></td><td><code>/api/admin/appearance/themes/{code}/impact</code></td><td>Report the impact of activating a theme</td></tr></tbody></table><h2 id="path-parameters" tabindex="-1">Path parameters <a class="header-anchor" href="#path-parameters" aria-label="Permalink to &quot;Path parameters&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Parameter</th><th>Description</th></tr></thead><tbody><tr><td><code>code</code></td><td>Theme code being considered.</td></tr></tbody></table><h2 id="query-parameters" tabindex="-1">Query parameters <a class="header-anchor" href="#query-parameters" aria-label="Permalink to &quot;Query parameters&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Parameter</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>channel_ids[]</code></td><td>Yes</td><td>Channels the theme would be applied to. Repeat for each channel.</td></tr></tbody></table><h2 id="response-fields" tabindex="-1">Response fields <a class="header-anchor" href="#response-fields" aria-label="Permalink to &quot;Response fields&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>code</code></td><td>string</td><td>The theme code that was asked about.</td></tr><tr><td><code>impact</code></td><td>array</td><td>One entry per affected channel. Empty when nothing would be left behind.</td></tr><tr><td><code>impact[].channelId</code></td><td>integer</td><td>Channel ID.</td></tr><tr><td><code>impact[].channel</code></td><td>string</td><td>Channel name.</td></tr><tr><td><code>impact[].currentTheme</code></td><td>string | null</td><td>Name of the theme the channel runs today.</td></tr><tr><td><code>impact[].customizations</code></td><td>integer</td><td>Sections the channel holds for that theme.</td></tr></tbody></table><h2 id="use-cases" tabindex="-1">Use cases <a class="header-anchor" href="#use-cases" aria-label="Permalink to &quot;Use cases&quot;">​</a></h2><ul><li><strong>Confirmation dialog before switching</strong> — call with the channels the merchant ticked; an empty <code>impact</code> means the switch is uneventful and the confirmation can be skipped.</li></ul><h2 id="best-practices" tabindex="-1">Best practices <a class="header-anchor" href="#best-practices" aria-label="Permalink to &quot;Best practices&quot;">​</a></h2><ul><li><strong>A channel already on this theme is never listed.</strong> <code>impact</code> counts only channels whose current theme differs, so an empty array is the normal answer when re-activating the theme a channel already runs.</li></ul><h2 id="errors" tabindex="-1">Errors <a class="header-anchor" href="#errors" aria-label="Permalink to &quot;Errors&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Status</th><th>When</th></tr></thead><tbody><tr><td><code>404</code></td><td>No theme with this code.</td></tr><tr><td><code>422</code></td><td><code>channel_ids</code> missing, or naming a channel that does not exist.</td></tr></tbody></table><h2 id="permissions" tabindex="-1">Permissions <a class="header-anchor" href="#permissions" aria-label="Permalink to &quot;Permissions&quot;">​</a></h2><p>Requires <code>appearance.themes</code>.</p>',19)]))}const u=t(r,[["render",i]]);export{m as __pageData,u as default};
